#include <cstdio>
#include <vector>

int main() {
    int n, q;
    scanf("%d %d", &n, &q);
    std::vector<long long> a(n);
    for (int i = 0; i < n; ++i) scanf("%lld", &a[i]);

    for (int t = 0; t < q; ++t) {
        long long x;
        scanf("%lld", &x);
        int lo = 0, hi = n - 1, ans = -1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (a[mid] == x) { ans = mid; break; }
            else if (a[mid] < x) lo = mid + 1;
            else hi = mid - 1;
        }
        printf("%d\n", ans);
    }
    return 0;
}
